<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\Hash;
use App\Models\{User,Zone,Alert,Guide,Contact};
class AlertaTest extends TestCase {
 use RefreshDatabase;
 private function staff($role='administrador'){ $u=User::factory()->create();$u->role=$role;$u->save();return $u; }
 private function zone(){return Zone::create(['name'=>'Socabaya','description'=>'Distrito de prueba']);}
 private function data($id){return ['title'=>'Prueba de alerta','zone_id'=>$id,'level'=>'alto','message'=>'Mensaje de demostraciÃ³n para prueba funcional.','source_url'=>'https://www.gob.pe/indeci','issued_at'=>now()->subMinute()->format('Y-m-d H:i:s'),'expires_at'=>now()->addDay()->format('Y-m-d H:i:s'),'status'=>'publicada'];}
 public function test_registration_hash_and_no_role_escalation():void{$this->post('/registro',['name'=>'Prueba','email'=>'prueba@example.test','password'=>'UnaClaveSegura123','password_confirmation'=>'UnaClaveSegura123','consent'=>'1','role'=>'administrador'])->assertRedirect('/cuenta');$u=User::first();$this->assertSame('ciudadano',$u->role);$this->assertTrue(Hash::check('UnaClaveSegura123',$u->password));}
 public function test_login_logout_and_bad_password():void{$u=$this->staff();$this->post('/login',['email'=>$u->email,'password'=>'incorrecta'])->assertSessionHasErrors('email');$this->post('/login',['email'=>$u->email,'password'=>'password'])->assertRedirect('/cuenta');$this->assertAuthenticatedAs($u);$this->post('/logout')->assertRedirect('/');$this->assertGuest();}
 public function test_permissions():void{$this->get('/gestion/alertas')->assertRedirect('/login');$this->actingAs($this->staff('ciudadano'))->get('/gestion/alertas')->assertForbidden();$this->actingAs($this->staff('operador'))->get('/gestion/zonas')->assertForbidden();$this->get('/gestion/guias')->assertOk();}
 public function test_all_four_crud():void{$this->actingAs($this->staff());$zone=$this->zone();$items=[['zonas',Zone::class,['name'=>'Miraflores','description'=>'Otra zona de prueba']],['guias',Guide::class,['title'=>'GuÃ­a original','body'=>'PreparaciÃ³n explicada en pasos de prueba.','source_url'=>'https://www.gob.pe/indeci']],['contactos',Contact::class,['name'=>'Contacto ficticio','phone'=>'000','source_url'=>'https://www.gob.pe/indeci']],['alertas',Alert::class,$this->data($zone->id)]];foreach($items as [$kind,$class,$data]){$this->get('/gestion/'.$kind.'/crear')->assertOk();$this->post('/gestion/'.$kind,$data)->assertSessionHasNoErrors()->assertRedirect('/gestion/'.$kind);$record=$class::latest('id')->first();$this->get('/gestion/'.$kind)->assertOk();$this->get('/gestion/'.$kind.'/'.$record->id.'/editar')->assertOk();$key=array_key_exists('title',$data)?'title':'name';$data[$key]='Registro actualizado';$this->put('/gestion/'.$kind.'/'.$record->id,$data)->assertSessionHasNoErrors();$this->assertSame('Registro actualizado',$record->fresh()->$key);$this->delete('/gestion/'.$kind.'/'.$record->id)->assertRedirect();$this->assertNull($class::find($record->id));}}
 public function test_validation_and_foreign_key():void{$this->actingAs($this->staff());$z=$this->zone();$data=$this->data($z->id);$data['source_url']='javascript:alert(1)';$this->post('/gestion/alertas',$data)->assertSessionHasErrors('source_url');$data=$this->data(999);$this->post('/gestion/alertas',$data)->assertSessionHasErrors('zone_id');$data=$this->data($z->id);$data['expires_at']=now()->subDay()->format('Y-m-d H:i:s');$this->post('/gestion/alertas',$data)->assertSessionHasErrors('expires_at');Alert::create($this->data($z->id));$this->delete('/gestion/zonas/'.$z->id)->assertSessionHasErrors('zone');$this->assertNotNull($z->fresh());}
 public function test_xss_sql_filter_and_expiry():void{$z=$this->zone();$data=$this->data($z->id);$data['title']='<script>alert(1)</script>';$a=Alert::create($data);$this->get('/')->assertOk()->assertDontSee('<script>alert(1)</script>',false)->assertSee('&lt;script&gt;alert(1)&lt;/script&gt;',false);$this->get('/?q='.urlencode("' OR 1=1 --"))->assertOk()->assertDontSee($data['title']);$a->update(['expires_at'=>now()->subSecond()]);$this->get('/')->assertDontSee($data['title']);$this->get('/alertas/'.$a->id)->assertSee('AVISO VENCIDO');$a->update(['status'=>'borrador']);$this->get('/alertas/'.$a->id)->assertNotFound();}
 public function test_notifications_segmented_and_owned():void{$z=$this->zone();$citizen=$this->staff('ciudadano');$citizen->update(['zone_id'=>$z->id]);$other=$this->staff('ciudadano');$this->actingAs($this->staff('operador'))->post('/gestion/alertas',$this->data($z->id))->assertSessionHasNoErrors();$this->assertSame(1,$citizen->notifications()->count());$this->assertSame(0,$other->notifications()->count());$n=$citizen->notifications()->first();$this->actingAs($other)->post('/avisos/'.$n->id.'/leido')->assertNotFound();$this->actingAs($citizen)->post('/avisos/'.$n->id.'/leido')->assertRedirect();$this->assertNotNull($n->fresh()->read_at);$this->get('/cuenta')->assertOk();}
 public function test_editing_published_alert_does_not_duplicate_notice():void{$z=$this->zone();$u=$this->staff('ciudadano');$u->update(['zone_id'=>$z->id]);$this->actingAs($this->staff())->post('/gestion/alertas',$this->data($z->id));$a=Alert::first();$this->put('/gestion/alertas/'.$a->id,$this->data($z->id))->assertSessionHasNoErrors();$this->assertSame(1,$u->notifications()->count());}
 public function test_preferences_and_unknown_kind():void{$z=$this->zone();$u=$this->staff();$this->actingAs($u)->put('/cuenta',['zone_id'=>$z->id])->assertSessionHasNoErrors();$this->assertSame($z->id,$u->fresh()->zone_id);$this->put('/cuenta',['zone_id'=>999])->assertSessionHasErrors('zone_id');$this->get('/gestion/users')->assertNotFound();}
 public function test_zone_summary_uses_all_matching_current_alerts():void {
 $z=$this->zone();
 for($i=0;$i<7;$i++){ $d=$this->data($z->id);$d['title']='Ejercicio '.$i;Alert::create($d); }
 $d=$this->data($z->id);$d['title']='Oculto';$d['status']='borrador';Alert::create($d);
 $d['status']='publicada';$d['expires_at']=now()->subMinute();Alert::create($d);
 $response=$this->get('/');$response->assertOk()->assertSee('Zonas afectadas y avisos por distrito')->assertSee('Sin reportes reales conectados')->assertDontSee('Oculto');
 $this->assertCount(7,$response->viewData('zoneSummaries')->first());
 $filtered=$this->get('/?q=Ejercicio%206');$this->assertCount(1,$filtered->viewData('zoneSummaries')->first());
 $this->get('/?q=inexistente')->assertSee('No hay avisos de demostración vigentes');
 }
}
